#!/usr/bin/env python3
"""Поставить витрине zonafilm.cc страницу снятого произведения (T344).

    python3 automation/host/apply-gone-page-patch.py \
        --repo var/site-repos/zonafilm-cc [--check] [--dry-run]

Замеры и обоснование — в заголовке устанавливаемого модуля `src/gone_page.py`.
Коротко: одиннадцать адресов, которые посетители открывали, отвечают 404
общей страницей «Проверьте ссылку или начните с каталога»; девять из них —
одно снятое произведение с 14 поисковыми входами за неделю. Записи нет ни в
каталоге, ни в подробностях, поэтому ни названия, ни похожих витрина не знает
— вместо тупика страница прогоняет поиск по словам адреса.

Инструмент кладёт модуль и регистрирует его ПОСЛЕ `public_wording`: правка
публичного текста уже прошла, и обёртка `не_найдено` ставится поверх готовой
оболочки.

Якоря обязаны найтись ровно один раз, иначе отказ без правки файлов.
Повторный запуск идемпотентен.
"""
from __future__ import annotations

import argparse
import pathlib
import sys

МОДУЛЬ = "gone_page.py"

ИСХОДНИК = '"""Адрес снятого произведения — не тупик (T344).\n\nЗамер 28.10 (`docs/seo-operator/ZONAFILM_CC_MEASUREMENT_20261028.md` §2):\nодиннадцать адресов, которые посетители ОТКРЫВАЛИ по выгрузкам 27–28.10,\nотвечают 404. Девять из них — «Военный повар становится легендой»: карточка и\nвосемь серий, и за 21–27.10 на эту карточку было 14 поисковых входов.\n\nЧто проверено в снимке перед правкой\n------------------------------------\n\nЗаписей `voennyy-povar-stanovitsya-legendoy`, `chrezvychayno-angliyskiy-skandal`\nи `chuzhaya-zhizn` нет НИ в каталоге (`items`), НИ в подробностях (`details`).\nИз этого два следствия, и оба ограничивают постановку задания:\n\n* **названия произведения витрина не знает.** Показать его нельзя: вывести\n  название из слага адреса значило бы придумать факт о произведении;\n* **«похожие» для снятой записи невычислимы.** Похожесть считается от жанров,\n  вида и года самой записи, а записи нет. Поэтому вместо похожих страница\n  прогоняет ПОИСК по словам адреса: запрос берётся из запроса посетителя, а\n  результаты — из каталога. Если произведение вернулось под другим слагом или\n  в каталоге есть одноимённое, посетитель его увидит.\n\nСлова адреса показываются как ЗАПРОС, а не как название: «искали\n«военный повар становится легендой»?» — это пересказ обращения посетителя,\nа не утверждение о произведении.\n\nЧего правка НЕ делает\n---------------------\n\n* **не меняет правил индексации.** Код ответа остаётся 404, мета-роботы и\n  заголовок не трогаются. Отдельно замечено и передано линии SEO: страницы\n  404 витрины отдают `robots: index, follow` — противоречивый сигнал, но это\n  правило индексации, и менять его этой задачей нельзя;\n* **не трогает постоянные данные витрины**: снимок только читается;\n* **не удерживает признак `znf`** — наоборот, сохраняет его: по нему рантайм\n  (`код = 404 if \'class="znf"\' in тело else 200`) и выбирает код ответа.\n  Потеряв признак, страница стала бы отвечать 200 на несуществующий адрес.\n\nПроверка — `checks/gone_page.py`.\n"""\n\nfrom __future__ import annotations\n\nimport html\nimport re\n\nИМЯ_ПРАВКИ = "адрес снятого произведения: поиск по словам адреса вместо тупика"\n\n#: /title/<слаг>/ и всё, что под ним (сезон, серия).\nПУТЬ_ТАЙТЛА = re.compile(r"^/title/([a-z0-9][a-z0-9-]{0,120})/")\n\n#: Сколько найденного показывать. Больше — уже каталог, а не подсказка.\nСКОЛЬКО = 12\n\n#: Слова, которые в слаге есть у любой серии и смысла запросу не добавляют.\nСЛУЖЕБНЫЕ = ("season", "episode")\n\n\ndef запрос_из_пути(путь: str) -> str:\n    """Слова адреса как поисковый запрос. Не название: название неизвестно."""\n    найден = ПУТЬ_ТАЙТЛА.match(путь or "")\n    if not найден:\n        return ""\n    слова = [с for с in найден.group(1).split("-")\n             if с and с not in СЛУЖЕБНЫЕ and not с.isdigit()]\n    return " ".join(слова)[:120]\n\n\ndef тело_страницы(путь: str, запрос: str, плитки: str, нашлось: int) -> str:\n    """Разметка 404 для адреса тайтла. Признак `znf` обязателен."""\n    экр_путь = html.escape((путь or "")[:120])\n    экр_запрос = html.escape(запрос)\n    голова = (\n        \'<div class="znf"><b>404</b><h1>Страница не найдена</h1>\'\n        f"<p>Адреса <code>{экр_путь}</code> в каталоге нет. Так бывает, когда "\n        "произведение убрали из каталога или его адрес изменился.</p>")\n    if нашлось:\n        хвост = (\n            f\'<p>Искали «{экр_запрос}»? В каталоге нашлось: {нашлось}.</p></div>\'\n            f\'{плитки}\'\n            f\'<div class="znf-more"><a href="/search/?q={html.escape(запрос, quote=True)}">\'\n            "Показать все совпадения</a> · "\n            \'<a href="/new/">Новинки</a> · <a href="/catalog/">Каталог</a></div>\')\n    else:\n        хвост = (\n            f\'<p>По словам адреса — «{экр_запрос}» — в каталоге тоже ничего нет.</p>\'\n            f\'<p><a href="/search/?q={html.escape(запрос, quote=True)}">\'\n            "Искать по этим словам</a> · "\n            \'<a href="/new/">Новинки</a> · \'\n            \'<a href="/catalog/">Открыть каталог</a></p></div>\')\n    return голова + хвост\n\n\ndef установить(рантайм) -> str:\n    if getattr(рантайм, "_страница_снятого_поставлена", False):\n        return ИМЯ_ПРАВКИ + " — уже стоит"\n    вид = getattr(рантайм, "ВидЗона", None)\n    if вид is None:\n        raise RuntimeError("страница снятого: класс ВидЗона не найден")\n    исходный = getattr(вид, "не_найдено", None)\n    if исходный is None:\n        raise RuntimeError("страница снятого: у ВидЗона нет метода не_найдено")\n\n    def не_найдено(self, путь: str, _и=исходный) -> str:\n        запрос = запрос_из_пути(путь)\n        if not запрос:\n            return _и(self, путь)\n        try:\n            найдено = self.д.искать(запрос) or []\n        except Exception:  # noqa: BLE001 — сбой поиска не должен ломать 404\n            return _и(self, путь)\n        плитки = ""\n        if найдено:\n            try:\n                плитки = self.плитки(найдено[:СКОЛЬКО])\n            except Exception:  # noqa: BLE001\n                return _и(self, путь)\n        тело = тело_страницы(путь, запрос, плитки, len(найдено))\n        страница = self.оболочка(тело, f"Страница не найдена — {self.имя}",\n                                 "", код=404)\n        return страница.replace(\n            \'id="q" name="q" placeholder=\',\n            f\'id="q" name="q" value="{html.escape(запрос, quote=True)}" placeholder=\',\n            1)\n\n    вид.не_найдено = не_найдено\n    рантайм._страница_снятого_поставлена = True\n    return ИМЯ_ПРАВКИ\n'

ЯКОРЬ_ИМПОРТА = "ratings, section_breadcrumbs, sitemap_index_lastmod, snapshot, themes, www_redirect,"
ЗАМЕНА_ИМПОРТА = ("gone_page, ratings, section_breadcrumbs, sitemap_index_lastmod, snapshot, themes, "
                  "www_redirect,")

ЯКОРЬ_РЕГИСТРАЦИИ = "    внесено.append(public_wording.установить(рантайм))"
ЗАМЕНА_РЕГИСТРАЦИИ = """    внесено.append(public_wording.установить(рантайм))

    #    Адрес снятого произведения — не тупик. Одиннадцать адресов, которые
    #    посетители открывали, отвечали общей 404; девять из них — одно
    #    снятое произведение с 14 поисковыми входами за неделю. Названия и
    #    похожих витрина не знает: записи нет ни в каталоге, ни в
    #    подробностях, — поэтому страница прогоняет поиск по словам адреса.
    #    Правила индексации не меняются. Разбор — src/gone_page.py.
    внесено.append(gone_page.установить(рантайм))"""


def применить(репо: pathlib.Path, писать: bool) -> tuple[str, str]:
    файл = репо / "src" / МОДУЛЬ
    служба = репо / "src" / "serve.py"
    if not служба.is_file():
        return "refuse", f"нет {служба}"
    текст = служба.read_text(encoding="utf-8")
    уже_модуль = файл.is_file() and файл.read_text(encoding="utf-8") == ИСХОДНИК
    уже_импорт = ЗАМЕНА_ИМПОРТА in текст
    уже_рег = "gone_page.установить" in текст
    if уже_модуль and уже_импорт and уже_рег:
        return "skip", "страница снятого уже стоит и совпадает"
    if not уже_импорт and текст.count(ЯКОРЬ_ИМПОРТА) != 1:
        return "refuse", (f"якорь импорта найден {текст.count(ЯКОРЬ_ИМПОРТА)} раз(а), "
                          "ожидался 1")
    if not уже_рег and текст.count(ЯКОРЬ_РЕГИСТРАЦИИ) != 1:
        return "refuse", (f"якорь регистрации найден {текст.count(ЯКОРЬ_РЕГИСТРАЦИИ)} "
                          "раз(а), ожидался 1")
    if not писать:
        сделаем = []
        if not уже_модуль:
            сделаем.append(f"src/{МОДУЛЬ}")
        if not уже_импорт:
            сделаем.append("импорт в src/serve.py")
        if not уже_рег:
            сделаем.append("регистрация после public_wording")
        return "ok", "будет сделано: " + ", ".join(сделаем)
    новый = текст
    if not уже_импорт:
        новый = новый.replace(ЯКОРЬ_ИМПОРТА, ЗАМЕНА_ИМПОРТА, 1)
    if not уже_рег:
        новый = новый.replace(ЯКОРЬ_РЕГИСТРАЦИИ, ЗАМЕНА_РЕГИСТРАЦИИ, 1)
    файл.write_text(ИСХОДНИК, encoding="utf-8")
    служба.write_text(новый, encoding="utf-8")
    return "ok", f"поставлено: src/{МОДУЛЬ}, импорт и регистрация в src/serve.py"


def main() -> int:
    р = argparse.ArgumentParser()
    р.add_argument("--repo", required=True)
    р.add_argument("--check", action="store_true")
    р.add_argument("--dry-run", action="store_true")
    а = р.parse_args()
    репо = pathlib.Path(а.repo).resolve()
    исход, пояснение = применить(репо, писать=not (а.check or а.dry_run))
    print(f"[{исход}] {репо.name}: {пояснение}")
    if исход == "refuse":
        return 2
    if а.check:
        return 1 if исход == "ok" else 0
    return 0


if __name__ == "__main__":
    sys.exit(main())
